from __future__ import annotations

import argparse
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]


def replace_once(text: str, old: str, new: str, label: str) -> str:
    if new in text:
        return text
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected one source anchor, found {count}")
    return text.replace(old, new, 1)


def replace_region(text: str, start: str, end: str, replacement: str, label: str) -> str:
    start_at = text.find(start)
    if start_at < 0:
        if replacement in text:
            return text
        raise RuntimeError(f"{label}: start anchor missing")
    end_at = text.find(end, start_at)
    if end_at < 0:
        raise RuntimeError(f"{label}: end anchor missing")
    existing = text[start_at:end_at]
    if existing == replacement:
        return text
    return text[:start_at] + replacement + text[end_at:]


def patch_streaming(text: str) -> str:
    start = "def execute_stream(\n"
    start_at = text.find(start)
    if start_at < 0:
        raise RuntimeError("streaming execute_stream anchor missing")
    replacement = '''def execute_stream(\n    request: inference_pb2.InferenceRequest,\n    *,\n    emit_chunk: Callable[[inference_pb2.InferenceChunk], None],\n    emit_terminal: Callable[[inference_pb2.InferenceTerminal], None],\n    engine_factory: Callable[[str], tuple[Any, type, type]] = _native_engine_factory,\n    artifact_path: Path | None = None,\n    host: str | None = None,\n    cancel_requested: Callable[[], bool] | None = None,\n    wait_for_cancel_ack: Callable[[float], bool] | None = None,\n    cancel_ack_timeout: float = 1.0,\n) -> None:\n    """Bridge native ``stream_full`` while preserving cancellation truth.\n\n    REQUESTED, ACK and terminal cessation are distinct. A CANCELLED terminal is\n    emitted only after the cancellation signal is observed locally and the\n    transport ACK is confirmed. Provider/remote cessation is not inferred.\n    """\n    validate_stream_request(request)\n    attest_pinned_artifact(artifact_path or _artifact_path())\n    resolved_host = host or _loopback_host()\n    parsed = urlparse(resolved_host)\n    if parsed.scheme != "http" or parsed.hostname not in {"127.0.0.1", "localhost", "::1"}:\n        raise UnaryInferenceRejected(\n            inference_pb2.INFERENCE_ERROR_CODE_ENGINE_UNAVAILABLE,\n            "non-loopback native endpoint rejected",\n            retryable=False,\n        )\n\n    def cancellation_is_requested() -> bool:\n        return bool(cancel_requested is not None and cancel_requested())\n\n    def emit_cancelled(sequence: int, usage: inference_pb2.InferenceUsage) -> None:\n        if wait_for_cancel_ack is None or not wait_for_cancel_ack(cancel_ack_timeout):\n            raise UnaryInferenceRejected(\n                inference_pb2.INFERENCE_ERROR_CODE_INTERNAL,\n                "local cancellation observed but transport ACK was not confirmed",\n                retryable=False,\n            )\n        emit_terminal(\n            inference_pb2.InferenceTerminal(\n                contract_version=contract_version(),\n                request_id=request.request_id,\n                attempt_id=request.attempt_id,\n                final_sequence=sequence,\n                finish_reason=inference_pb2.INFERENCE_FINISH_REASON_CANCELLED,\n                usage=usage,\n            )\n        )\n\n    engine = None\n    try:\n        engine, message_type, role_type = engine_factory(resolved_host)\n        messages = _messages(request, message_type, role_type)\n        temperature = request.config.temperature if request.config.HasField("temperature") else 0.0\n\n        async def consume() -> None:\n            sequence = 0\n            finish_reason = inference_pb2.INFERENCE_FINISH_REASON_UNSPECIFIED\n            usage = inference_pb2.InferenceUsage(\n                measurement=inference_pb2.INFERENCE_USAGE_MEASUREMENT_UNKNOWN\n            )\n            saw_finish = False\n            if cancellation_is_requested():\n                emit_cancelled(sequence, usage)\n                return\n            async for native in engine.stream_full(\n                messages,\n                model=PINNED_MODEL_ID,\n                temperature=float(temperature),\n                max_tokens=int(request.config.max_output_tokens),\n                chat_template_kwargs={"enable_thinking": False},\n            ):\n                if cancellation_is_requested():\n                    emit_cancelled(sequence, usage)\n                    return\n\n                content = getattr(native, "content", None)\n                tool_calls = getattr(native, "tool_calls", None)\n                content_blocks = getattr(native, "content_blocks", None)\n                tool_results = getattr(native, "tool_results", None)\n                native_finish = getattr(native, "finish_reason", None)\n                native_usage = getattr(native, "usage", None)\n\n                if saw_finish and any(\n                    value not in (None, [], {}, "")\n                    for value in (content, tool_calls, content_blocks, tool_results, native_finish, native_usage)\n                ):\n                    raise UnaryInferenceRejected(\n                        inference_pb2.INFERENCE_ERROR_CODE_INTERNAL,\n                        "native stream emitted data after finish_reason",\n                        retryable=False,\n                    )\n                if tool_calls or content_blocks or tool_results:\n                    raise UnaryInferenceRejected(\n                        inference_pb2.INFERENCE_ERROR_CODE_INTERNAL,\n                        "typed/tool streaming fragments are deferred to W02-13",\n                        retryable=False,\n                    )\n                if content is not None:\n                    if not isinstance(content, str):\n                        raise UnaryInferenceRejected(\n                            inference_pb2.INFERENCE_ERROR_CODE_INTERNAL,\n                            "native streaming content must be text",\n                            retryable=False,\n                        )\n                    if content:\n                        sequence += 1\n                        emit_chunk(\n                            inference_pb2.InferenceChunk(\n                                contract_version=contract_version(),\n                                request_id=request.request_id,\n                                attempt_id=request.attempt_id,\n                                sequence=sequence,\n                                text_delta=content,\n                            )\n                        )\n                if native_usage is not None:\n                    usage = _usage(native_usage)\n                if native_finish is not None:\n                    if saw_finish:\n                        raise UnaryInferenceRejected(\n                            inference_pb2.INFERENCE_ERROR_CODE_INTERNAL,\n                            "native stream emitted duplicate finish_reason",\n                            retryable=False,\n                        )\n                    finish_reason = _finish_reason(native_finish)\n                    saw_finish = True\n                if cancellation_is_requested():\n                    emit_cancelled(sequence, usage)\n                    return\n\n            if cancellation_is_requested():\n                emit_cancelled(sequence, usage)\n                return\n            if sequence == 0:\n                raise UnaryInferenceRejected(\n                    inference_pb2.INFERENCE_ERROR_CODE_INTERNAL,\n                    "native stream ended without content chunks",\n                    retryable=False,\n                )\n            emit_terminal(\n                inference_pb2.InferenceTerminal(\n                    contract_version=contract_version(),\n                    request_id=request.request_id,\n                    attempt_id=request.attempt_id,\n                    final_sequence=sequence,\n                    finish_reason=finish_reason,\n                    usage=usage,\n                )\n            )\n\n        asyncio.run(consume())\n    except UnaryInferenceRejected:\n        raise\n    except Exception as exc:\n        raise UnaryInferenceRejected(\n            inference_pb2.INFERENCE_ERROR_CODE_ENGINE_UNAVAILABLE,\n            f"native OpenJarvis streaming execution failed: {type(exc).__name__}: {exc}",\n            retryable=False,\n        ) from exc\n    finally:\n        if engine is not None:\n            close = getattr(engine, "close", None)\n            if callable(close):\n                with contextlib.suppress(Exception):\n                    close()\n'''
    return text[:start_at] + replacement


def patch_sidecar(text: str) -> str:
    text = replace_once(text, "import struct\nimport sys\nimport time\n", "import struct\nimport sys\nimport threading\nimport time\n", "sidecar threading import")
    text = replace_once(
        text,
        "_RESERVED_METADATA_TOKENS = (\n",
        '''class _ActiveInference:\n    def __init__(self, request_id: str, attempt_id: str, frame_id: str) -> None:\n        self.request_id = request_id\n        self.attempt_id = attempt_id\n        self.frame_id = frame_id\n        self.cancel_requested = threading.Event()\n        self.cancel_acknowledged = threading.Event()\n\n\nclass _InferenceCoordinator:\n    """Single-flight request/attempt ownership for the W02-12 streaming lane."""\n\n    def __init__(self) -> None:\n        self._lock = threading.Lock()\n        self._active: _ActiveInference | None = None\n        self._last_terminal: tuple[str, str] | None = None\n\n    def begin(self, request_id: str, attempt_id: str, frame_id: str) -> _ActiveInference | None:\n        with self._lock:\n            if self._active is not None:\n                return None\n            state = _ActiveInference(request_id, attempt_id, frame_id)\n            self._active = state\n            return state\n\n    def busy(self) -> bool:\n        with self._lock:\n            return self._active is not None\n\n    def request_cancel(self, request_id: str, attempt_id: str) -> tuple[str, _ActiveInference | None]:\n        with self._lock:\n            if (\n                self._active is not None\n                and self._active.request_id == request_id\n                and self._active.attempt_id == attempt_id\n            ):\n                self._active.cancel_requested.set()\n                return "REQUESTED", self._active\n            if self._last_terminal == (request_id, attempt_id):\n                return "ALREADY_TERMINAL", None\n            return "NOT_ACTIVE", None\n\n    def complete_normal(self, state: _ActiveInference) -> bool:\n        with self._lock:\n            if self._active is not state or state.cancel_requested.is_set():\n                return False\n            self._active = None\n            self._last_terminal = (state.request_id, state.attempt_id)\n            return True\n\n    def complete_cancelled(self, state: _ActiveInference) -> None:\n        with self._lock:\n            if self._active is state:\n                self._active = None\n            self._last_terminal = (state.request_id, state.attempt_id)\n\n    def fail(self, state: _ActiveInference) -> None:\n        with self._lock:\n            if self._active is state:\n                self._active = None\n\n\n_RESERVED_METADATA_TOKENS = (\n''',
        "sidecar inference coordinator",
    )
    text = replace_once(
        text,
        '            "streaming-inference",\n        ],\n',
        '            "streaming-inference",\n            "streaming-cancellation",\n        ],\n',
        "sidecar cancellation feature",
    )
    start = "def run_protocol(stdin: BinaryIO, stdout: BinaryIO) -> int:\n"
    end = "\ndef main() -> int:\n"
    replacement = '''def run_protocol(stdin: BinaryIO, stdout: BinaryIO) -> int:\n    snapshot, diagnostics = discover_registry_snapshot()\n    write_frame(stdout, hello_frame())\n    first = read_frame(stdin)\n    if first is None or first.WhichOneof("body") != "hello_ack" or not first.hello_ack.accepted:\n        return 64\n\n    write_lock = threading.Lock()\n    coordinator = _InferenceCoordinator()\n\n    def send(frame: adapter_pb2.AdapterFrame) -> None:\n        with write_lock:\n            write_frame(stdout, frame)\n\n    def adapter_error(request: adapter_pb2.AdapterFrame, code: str, message: str) -> None:\n        send(\n            _frame(\n                f"adapter-error:{request.frame_id}",\n                "error",\n                adapter_pb2.AdapterError(code=code, message=message, retryable=False),\n                correlation_id=request.frame_id,\n            )\n        )\n\n    def inference_error(request: adapter_pb2.AdapterFrame, code: int, message: str) -> None:\n        native = request.inference_request\n        send(\n            _frame(\n                f"inference-error:{request.frame_id}",\n                "inference_error",\n                inference_pb2.InferenceError(\n                    contract_version=common_pb2.ContractVersion(major=1, minor=2),\n                    request_id=native.request_id,\n                    attempt_id=native.attempt_id,\n                    code=code,\n                    message=message,\n                    retryable=False,\n                ),\n                correlation_id=request.frame_id,\n            )\n        )\n\n    def start_stream(request: adapter_pb2.AdapterFrame) -> bool:\n        native_request = request.inference_request\n        state = coordinator.begin(native_request.request_id, native_request.attempt_id, request.frame_id)\n        if state is None:\n            inference_error(\n                request,\n                inference_pb2.INFERENCE_ERROR_CODE_BUSY,\n                "W02-12 sidecar is explicit single-flight; another inference is active",\n            )\n            return False\n\n        def worker() -> None:\n            def emit_chunk(chunk: inference_pb2.InferenceChunk) -> None:\n                send(\n                    _frame(\n                        f"inference-chunk:{request.frame_id}:{chunk.sequence}",\n                        "inference_chunk",\n                        chunk,\n                        correlation_id=request.frame_id,\n                    )\n                )\n\n            def emit_terminal(terminal: inference_pb2.InferenceTerminal) -> None:\n                if terminal.finish_reason == inference_pb2.INFERENCE_FINISH_REASON_CANCELLED:\n                    if not state.cancel_acknowledged.wait(1.0):\n                        raise UnaryInferenceRejected(\n                            inference_pb2.INFERENCE_ERROR_CODE_INTERNAL,\n                            "cancelled terminal attempted before transport ACK",\n                            retryable=False,\n                        )\n                    coordinator.complete_cancelled(state)\n                    send(\n                        _frame(\n                            f"inference-terminal:{request.frame_id}",\n                            "inference_terminal",\n                            terminal,\n                            correlation_id=request.frame_id,\n                        )\n                    )\n                    return\n\n                if coordinator.complete_normal(state):\n                    send(\n                        _frame(\n                            f"inference-terminal:{request.frame_id}",\n                            "inference_terminal",\n                            terminal,\n                            correlation_id=request.frame_id,\n                        )\n                    )\n                    return\n\n                if not state.cancel_requested.is_set() or not state.cancel_acknowledged.wait(1.0):\n                    raise UnaryInferenceRejected(\n                        inference_pb2.INFERENCE_ERROR_CODE_INTERNAL,\n                        "stream terminal raced cancellation without an ACK",\n                        retryable=False,\n                    )\n                cancelled = inference_pb2.InferenceTerminal(\n                    contract_version=common_pb2.ContractVersion(major=1, minor=2),\n                    request_id=native_request.request_id,\n                    attempt_id=native_request.attempt_id,\n                    final_sequence=terminal.final_sequence,\n                    finish_reason=inference_pb2.INFERENCE_FINISH_REASON_CANCELLED,\n                    usage=inference_pb2.InferenceUsage(\n                        measurement=inference_pb2.INFERENCE_USAGE_MEASUREMENT_UNKNOWN\n                    ),\n                )\n                coordinator.complete_cancelled(state)\n                send(\n                    _frame(\n                        f"inference-terminal:{request.frame_id}",\n                        "inference_terminal",\n                        cancelled,\n                        correlation_id=request.frame_id,\n                    )\n                )\n\n            try:\n                execute_stream(\n                    native_request,\n                    emit_chunk=emit_chunk,\n                    emit_terminal=emit_terminal,\n                    cancel_requested=state.cancel_requested.is_set,\n                    wait_for_cancel_ack=state.cancel_acknowledged.wait,\n                )\n            except UnaryInferenceRejected as exc:\n                send(\n                    _frame(\n                        f"inference-error:{request.frame_id}",\n                        "inference_error",\n                        inference_pb2.InferenceError(\n                            contract_version=common_pb2.ContractVersion(major=1, minor=2),\n                            request_id=native_request.request_id,\n                            attempt_id=native_request.attempt_id,\n                            code=exc.code,\n                            message=str(exc),\n                            retryable=exc.retryable,\n                        ),\n                        correlation_id=request.frame_id,\n                    )\n                )\n            finally:\n                coordinator.fail(state)\n\n        threading.Thread(target=worker, name=f"openjarvis-stream-{native_request.attempt_id}", daemon=True).start()\n        return True\n\n    while True:\n        request = read_frame(stdin)\n        if request is None:\n            return 0\n        body = request.WhichOneof("body")\n        if body == "registry_snapshot_request":\n            response = _frame(\n                f"registry:{request.frame_id}",\n                "registry_snapshot",\n                snapshot,\n                correlation_id=request.frame_id,\n            )\n            send(response)\n        elif body == "health_request":\n            send(health_frame(reasons=diagnostics["unsupported_registries"], correlation_id=request.frame_id))\n        elif body == "cancel":\n            # Legacy adapter-control cancellation remains a no-op health acknowledgement.\n            send(health_frame(correlation_id=request.frame_id))\n        elif body == "inference_cancel":\n            cancel = request.inference_cancel\n            if (\n                not cancel.HasField("contract_version")\n                or cancel.contract_version.major != 1\n                or cancel.contract_version.minor > 2\n                or not cancel.target_request_id.strip()\n                or not cancel.target_attempt_id.strip()\n                or not cancel.reason.strip()\n            ):\n                adapter_error(request, "CANCEL_INVALID", "inference cancellation target/reason is invalid")\n                continue\n            status, state = coordinator.request_cancel(cancel.target_request_id, cancel.target_attempt_id)\n            if status == "REQUESTED" and state is not None:\n                send(\n                    _frame(\n                        f"inference-cancel-ack:{request.frame_id}",\n                        "inference_cancel",\n                        cancel,\n                        correlation_id=request.frame_id,\n                    )\n                )\n                state.cancel_acknowledged.set()\n            elif status == "ALREADY_TERMINAL":\n                adapter_error(\n                    request,\n                    "CANCEL_ALREADY_TERMINAL",\n                    "target request/attempt already reached a terminal state",\n                )\n            else:\n                adapter_error(\n                    request,\n                    "CANCEL_NOT_ACTIVE",\n                    "target request/attempt is not the active single-flight inference",\n                )\n        elif body == "inference_request":\n            native_request = request.inference_request\n            if native_request.HasField("config") and native_request.config.stream:\n                start_stream(request)\n                continue\n            if coordinator.busy():\n                inference_error(\n                    request,\n                    inference_pb2.INFERENCE_ERROR_CODE_BUSY,\n                    "W02-12 sidecar is explicit single-flight; another inference is active",\n                )\n                continue\n            try:\n                outcome = execute_unary(native_request)\n            except UnaryInferenceRejected as exc:\n                send(\n                    _frame(\n                        f"inference-error:{request.frame_id}",\n                        "inference_error",\n                        inference_pb2.InferenceError(\n                            contract_version=common_pb2.ContractVersion(major=1, minor=2),\n                            request_id=native_request.request_id,\n                            attempt_id=native_request.attempt_id,\n                            code=exc.code,\n                            message=str(exc),\n                            retryable=exc.retryable,\n                        ),\n                        correlation_id=request.frame_id,\n                    )\n                )\n                continue\n            send(\n                _frame(\n                    f"inference-chunk:{request.frame_id}",\n                    "inference_chunk",\n                    outcome.chunk,\n                    correlation_id=request.frame_id,\n                )\n            )\n            send(\n                _frame(\n                    f"inference-terminal:{request.frame_id}",\n                    "inference_terminal",\n                    outcome.terminal,\n                    correlation_id=request.frame_id,\n                )\n            )\n        elif body == "shutdown":\n            seconds, nanos = _now_timestamp()\n            stopping = runtime_pb2.RuntimeHealth(\n                contract_version=contract_version(),\n                runtime_id=RUNTIME_ID,\n                status=runtime_pb2.RUNTIME_HEALTH_STATUS_STOPPING,\n            )\n            stopping.observed_at.seconds = seconds\n            stopping.observed_at.nanos = nanos\n            send(_frame("openjarvis-stopping", "health", stopping, correlation_id=request.frame_id))\n            return 0\n        else:\n            adapter_error(request, "UNSUPPORTED_BODY", str(body))\n'''
    return replace_region(text, start, end, replacement, "sidecar protocol")


def patch_fake_sidecar(text: str) -> str:
    text = replace_once(
        text,
        '''def stream_terminal(request, final_sequence: int) -> adapter_pb2.AdapterFrame:\n    body = inference_pb2.InferenceTerminal(\n        contract_version=inference_version(),\n        request_id=request.request_id,\n        attempt_id=request.attempt_id,\n        final_sequence=final_sequence,\n        finish_reason=inference_pb2.INFERENCE_FINISH_REASON_STOP,\n        usage=inference_pb2.InferenceUsage(\n            measurement=inference_pb2.INFERENCE_USAGE_MEASUREMENT_UNKNOWN\n        ),\n    )\n    return frame(\n        "stream-terminal",\n        "inference_terminal",\n        body,\n        correlation_id="__REQUEST_FRAME__",\n    )\n\n\n''',
        '''def stream_terminal(request, final_sequence: int) -> adapter_pb2.AdapterFrame:\n    body = inference_pb2.InferenceTerminal(\n        contract_version=inference_version(),\n        request_id=request.request_id,\n        attempt_id=request.attempt_id,\n        final_sequence=final_sequence,\n        finish_reason=inference_pb2.INFERENCE_FINISH_REASON_STOP,\n        usage=inference_pb2.InferenceUsage(\n            measurement=inference_pb2.INFERENCE_USAGE_MEASUREMENT_UNKNOWN\n        ),\n    )\n    return frame(\n        "stream-terminal",\n        "inference_terminal",\n        body,\n        correlation_id="__REQUEST_FRAME__",\n    )\n\n\ndef cancelled_terminal(request, final_sequence: int) -> adapter_pb2.AdapterFrame:\n    body = inference_pb2.InferenceTerminal(\n        contract_version=inference_version(),\n        request_id=request.request_id,\n        attempt_id=request.attempt_id,\n        final_sequence=final_sequence,\n        finish_reason=inference_pb2.INFERENCE_FINISH_REASON_CANCELLED,\n        usage=inference_pb2.InferenceUsage(\n            measurement=inference_pb2.INFERENCE_USAGE_MEASUREMENT_UNKNOWN\n        ),\n    )\n    return frame(\n        "stream-cancelled-terminal",\n        "inference_terminal",\n        body,\n        correlation_id="__REQUEST_FRAME__",\n    )\n\n\ndef require_cancel(envelope, request):\n    cancel_frame = read_frame()\n    if cancel_frame is None or cancel_frame.WhichOneof("body") != "inference_cancel":\n        raise SystemExit(93)\n    cancel = cancel_frame.inference_cancel\n    if cancel.target_request_id != request.request_id or cancel.target_attempt_id != request.attempt_id:\n        raise SystemExit(94)\n    ack = frame(\n        f"cancel-ack:{cancel_frame.frame_id}",\n        "inference_cancel",\n        cancel,\n        correlation_id=cancel_frame.frame_id,\n    )\n    write_frame(ack)\n    return cancel_frame\n\n\n''',
        "fake cancellation helpers",
    )
    text = replace_once(
        text,
        '            "streaming-inference",\n        ],\n',
        '            "streaming-inference",\n            "streaming-cancellation",\n        ],\n',
        "fake cancellation feature",
    )
    start = '''    if mode.startswith("stream-"):\n'''
    end = '''    while True:\n'''
    replacement = '''    if mode.startswith("stream-"):\n        envelope = read_frame()\n        if envelope is None or envelope.WhichOneof("body") != "inference_request":\n            return 65\n        request = envelope.inference_request\n        first = stream_chunk(request, 1, "hé")\n        second = stream_chunk(request, 2, "llo")\n        terminal = stream_terminal(request, 2)\n        for value in (first, second, terminal):\n            value.correlation_id = envelope.frame_id\n        if mode == "stream-valid":\n            write_fragmented_utf8_frame(first)\n            write_coalesced(second, terminal)\n            return 0\n        if mode == "stream-duplicate":\n            duplicate = stream_chunk(request, 1, "duplicate")\n            duplicate.correlation_id = envelope.frame_id\n            write_coalesced(first, duplicate, terminal)\n            return 0\n        if mode == "stream-reordered":\n            write_coalesced(second, terminal)\n            return 0\n        if mode == "stream-eof":\n            write_frame(first)\n            return 0\n        if mode == "stream-cancel-before":\n            require_cancel(envelope, request)\n            cancelled = cancelled_terminal(request, 0)\n            cancelled.correlation_id = envelope.frame_id\n            write_frame(cancelled)\n            return 0\n        if mode == "stream-cancel-during":\n            write_frame(first)\n            require_cancel(envelope, request)\n            cancelled = cancelled_terminal(request, 1)\n            cancelled.correlation_id = envelope.frame_id\n            write_frame(cancelled)\n            return 0\n        if mode == "stream-cancel-ignore":\n            write_frame(first)\n            require_cancel(envelope, request)\n            time.sleep(2)\n            return 0\n        if mode == "stream-cancel-after-terminal":\n            one_terminal = stream_terminal(request, 1)\n            one_terminal.correlation_id = envelope.frame_id\n            write_coalesced(first, one_terminal)\n            cancel_frame = read_frame()\n            if cancel_frame is None or cancel_frame.WhichOneof("body") != "inference_cancel":\n                return 67\n            error = adapter_pb2.AdapterError(\n                code="CANCEL_ALREADY_TERMINAL",\n                message="target already terminal",\n                retryable=False,\n            )\n            write_frame(\n                frame(\n                    f"cancel-error:{cancel_frame.frame_id}",\n                    "error",\n                    error,\n                    correlation_id=cancel_frame.frame_id,\n                )\n            )\n            time.sleep(0.2)\n            return 0\n        return 66\n\n'''
    return replace_region(text, start, end, replacement, "fake streaming modes")


def patch_adapter(text: str) -> str:
    text = replace_once(
        text,
        "    AdapterShutdown, CapabilityDescriptor, ContractVersion, InferenceChunk, InferenceError,\n",
        "    AdapterShutdown, CapabilityDescriptor, ContractVersion, InferenceCancel, InferenceChunk, InferenceError,\n",
        "adapter cancellation import",
    )
    text = replace_once(
        text,
        'const OPTIONAL_FEATURES: [&str; 2] = ["unary-inference", "streaming-inference"];\n',
        'const OPTIONAL_FEATURES: [&str; 3] = ["unary-inference", "streaming-inference", "streaming-cancellation"];\n',
        "adapter cancellation feature",
    )
    text = replace_once(
        text,
        '''#[derive(Debug, Clone, PartialEq)]\npub struct StreamingInferenceResult {\n    pub chunks: Vec<InferenceChunk>,\n    pub text: String,\n    pub terminal: InferenceTerminal,\n}\n''',
        '''#[derive(Debug, Clone, PartialEq)]\npub struct StreamingInferenceResult {\n    pub chunks: Vec<InferenceChunk>,\n    pub text: String,\n    pub terminal: InferenceTerminal,\n}\n\n#[derive(Debug, Clone, PartialEq)]\npub struct CancelledStreamingInferenceResult {\n    pub chunks: Vec<InferenceChunk>,\n    pub text: String,\n    pub terminal: InferenceTerminal,\n    pub cancellation_requested: bool,\n    pub cancellation_acknowledged: bool,\n}\n\n#[derive(Debug, Clone, Copy, PartialEq, Eq)]\npub enum InferenceCancelOutcome {\n    Acknowledged,\n    AlreadyTerminal,\n}\n''',
        "adapter cancellation result types",
    )
    anchor = '''    fn validate_stream_chunk(\n'''
    if "pub fn infer_stream_with_cancellation(" not in text:
        at = text.find(anchor)
        if at < 0:
            raise RuntimeError("adapter stream validation anchor missing")
        methods = '''    fn send_inference_cancel_frame(\n        &mut self,\n        target_request_id: &str,\n        target_attempt_id: &str,\n        reason: &str,\n    ) -> Result<String, AdapterSupervisorError> {\n        if target_request_id.trim().is_empty()\n            || target_attempt_id.trim().is_empty()\n            || reason.trim().is_empty()\n        {\n            return Err(AdapterSupervisorError::InvalidInferenceRequest(\n                "cancellation request_id, attempt_id and reason must be non-empty".to_owned(),\n            ));\n        }\n        let frame = self.next_control_frame(\n            adapter_frame::Body::InferenceCancel(InferenceCancel {\n                contract_version: Some(ContractVersion { major: 1, minor: 2 }),\n                target_request_id: target_request_id.to_owned(),\n                target_attempt_id: target_attempt_id.to_owned(),\n                reason: reason.to_owned(),\n            }),\n            self.policy.request_timeout,\n        );\n        let frame_id = frame.frame_id.clone();\n        if let Err(error) = self.write_frame(&frame) {\n            return self.fail_protocol(error);\n        }\n        Ok(frame_id)\n    }\n\n    fn validate_inference_cancel_ack(\n        &mut self,\n        frame: &AdapterFrame,\n        cancel_frame_id: &str,\n        request: &InferenceRequest,\n    ) -> Result<(), AdapterSupervisorError> {\n        if frame.frame_id.trim().is_empty() || frame.correlation_id != cancel_frame_id {\n            return self.fail_protocol(AdapterSupervisorError::InvalidRuntimeResponse(\n                "cancellation ACK correlation mismatch".to_owned(),\n            ));\n        }\n        let ack = match frame.body.as_ref() {\n            Some(adapter_frame::Body::InferenceCancel(value)) => value,\n            _ => {\n                return self.fail_protocol(AdapterSupervisorError::UnexpectedFrame(\n                    "inference cancellation ACK",\n                ))\n            }\n        };\n        if let Err(error) = validate_contract_version(ack.contract_version.as_ref()) {\n            return self.fail_protocol(error.into());\n        }\n        if ack.target_request_id != request.request_id\n            || ack.target_attempt_id != request.attempt_id\n            || ack.reason.trim().is_empty()\n        {\n            return self.fail_protocol(AdapterSupervisorError::InvalidRuntimeResponse(\n                "cancellation ACK target/reason mismatch".to_owned(),\n            ));\n        }\n        Ok(())\n    }\n\n    pub fn cancel_inference(\n        &mut self,\n        target_request_id: impl Into<String>,\n        target_attempt_id: impl Into<String>,\n        reason: impl Into<String>,\n    ) -> Result<InferenceCancelOutcome, AdapterSupervisorError> {\n        self.ensure_io_healthy()?;\n        if !self.negotiated_features.contains("streaming-cancellation") {\n            return Err(AdapterSupervisorError::InvalidInferenceRequest(\n                "peer did not negotiate streaming-cancellation".to_owned(),\n            ));\n        }\n        let request_id = target_request_id.into();\n        let attempt_id = target_attempt_id.into();\n        let reason = reason.into();\n        let cancel_frame_id =\n            self.send_inference_cancel_frame(&request_id, &attempt_id, &reason)?;\n        let response = match self.receive_frame(self.policy.request_timeout, "inference cancellation ACK") {\n            Ok(response) => response,\n            Err(error) => return self.fail_protocol(error),\n        };\n        if response.frame_id.trim().is_empty() || response.correlation_id != cancel_frame_id {\n            return self.fail_protocol(AdapterSupervisorError::InvalidRuntimeResponse(\n                "cancellation response correlation mismatch".to_owned(),\n            ));\n        }\n        match response.body {\n            Some(adapter_frame::Body::InferenceCancel(ack)) => {\n                if let Err(error) = validate_contract_version(ack.contract_version.as_ref()) {\n                    return self.fail_protocol(error.into());\n                }\n                if ack.target_request_id != request_id || ack.target_attempt_id != attempt_id {\n                    return self.fail_protocol(AdapterSupervisorError::InvalidRuntimeResponse(\n                        "cancellation ACK target mismatch".to_owned(),\n                    ));\n                }\n                Ok(InferenceCancelOutcome::Acknowledged)\n            }\n            Some(adapter_frame::Body::Error(error)) if error.code == "CANCEL_ALREADY_TERMINAL" => {\n                Ok(InferenceCancelOutcome::AlreadyTerminal)\n            }\n            Some(adapter_frame::Body::Error(error)) => Err(AdapterSupervisorError::InvalidRuntimeResponse(\n                format!("cancellation rejected {}: {}", error.code, error.message),\n            )),\n            _ => self.fail_protocol(AdapterSupervisorError::UnexpectedFrame(\n                "inference cancellation response",\n            )),\n        }\n    }\n\n    pub fn infer_stream_with_cancellation(\n        &mut self,\n        request: InferenceRequest,\n        cancel_after_chunks: usize,\n        reason: impl Into<String>,\n    ) -> Result<CancelledStreamingInferenceResult, AdapterSupervisorError> {\n        self.ensure_io_healthy()?;\n        if !self.negotiated_features.contains("streaming-inference")\n            || !self.negotiated_features.contains("streaming-cancellation")\n        {\n            return self.fail_protocol(AdapterSupervisorError::InvalidInferenceRequest(\n                "peer did not negotiate streaming inference cancellation".to_owned(),\n            ));\n        }\n        let reason = reason.into();\n        if reason.trim().is_empty() {\n            return Err(AdapterSupervisorError::InvalidInferenceRequest(\n                "cancellation reason must be non-empty".to_owned(),\n            ));\n        }\n        let reservation = InferenceReservation {\n            estimated_input_tokens: 0,\n            estimated_cost_microusd: 0,\n        };\n        let local_target = InferenceTarget {\n            provider_id: "openjarvis.llamacpp".to_owned(),\n            origin: "loopback".to_owned(),\n            external: false,\n        };\n        authorize_inference_egress(&request, &local_target, None, &reservation, 0)\n            .map_err(|error| AdapterSupervisorError::InvalidInferenceRequest(error.to_string()))?;\n        let config = request.config.as_ref().ok_or_else(|| {\n            AdapterSupervisorError::InvalidInferenceRequest("config is required".to_owned())\n        })?;\n        if request.engine_id != W02_UNARY_ENGINE_ID\n            || request.model_id != W02_UNARY_MODEL_ID\n            || request.idempotency_key.trim().is_empty()\n            || request.inputs.is_empty()\n            || request.deadline_at.is_none()\n            || !config.stream\n            || config.max_output_tokens == 0\n            || config.max_output_tokens > 256\n            || request\n                .inputs\n                .iter()\n                .any(|input| input.role == 0 || input.content.trim().is_empty())\n        {\n            return self.fail_protocol(AdapterSupervisorError::InvalidInferenceRequest(\n                "request is outside the bounded W02-12 cancellation lane".to_owned(),\n            ));\n        }\n\n        let frame = self.next_control_frame(\n            adapter_frame::Body::InferenceRequest(request.clone()),\n            self.policy.request_timeout,\n        );\n        let request_frame_id = frame.frame_id.clone();\n        if let Err(error) = self.write_frame(&frame) {\n            return self.fail_protocol(error);\n        }\n\n        let mut chunks = Vec::new();\n        let mut text = String::new();\n        let mut expected_sequence = 1_u64;\n        let mut cancel_frame_id = None;\n        let mut cancellation_acknowledged = false;\n        if cancel_after_chunks == 0 {\n            cancel_frame_id = Some(self.send_inference_cancel_frame(\n                &request.request_id,\n                &request.attempt_id,\n                &reason,\n            )?);\n        }\n\n        loop {\n            let response = match self.receive_frame(\n                self.policy.request_timeout,\n                "inference cancellation termination",\n            ) {\n                Ok(response) => response,\n                Err(error) => return self.fail_protocol(error),\n            };\n            match response.body.as_ref() {\n                Some(adapter_frame::Body::InferenceCancel(_)) => {\n                    let expected = match cancel_frame_id.as_deref() {\n                        Some(value) => value,\n                        None => {\n                            return self.fail_protocol(AdapterSupervisorError::InvalidRuntimeResponse(\n                                "unsolicited cancellation ACK".to_owned(),\n                            ))\n                        }\n                    };\n                    self.validate_inference_cancel_ack(&response, expected, &request)?;\n                    if cancellation_acknowledged {\n                        return self.fail_protocol(AdapterSupervisorError::InvalidRuntimeResponse(\n                            "duplicate cancellation ACK".to_owned(),\n                        ));\n                    }\n                    cancellation_acknowledged = true;\n                }\n                Some(adapter_frame::Body::InferenceChunk(_)) => {\n                    self.validate_inference_outer(&response, &request_frame_id)?;\n                    let chunk = match response.body {\n                        Some(adapter_frame::Body::InferenceChunk(chunk)) => chunk,\n                        _ => unreachable!(),\n                    };\n                    self.validate_stream_chunk(&chunk, &request, expected_sequence)?;\n                    text.push_str(&chunk.text_delta);\n                    chunks.push(chunk);\n                    expected_sequence = expected_sequence.saturating_add(1);\n                    if cancel_frame_id.is_none() && chunks.len() >= cancel_after_chunks {\n                        cancel_frame_id = Some(self.send_inference_cancel_frame(\n                            &request.request_id,\n                            &request.attempt_id,\n                            &reason,\n                        )?);\n                    }\n                }\n                Some(adapter_frame::Body::InferenceTerminal(_)) => {\n                    self.validate_inference_outer(&response, &request_frame_id)?;\n                    if cancel_frame_id.is_none() {\n                        return self.fail_protocol(AdapterSupervisorError::InvalidRuntimeResponse(\n                            "stream reached terminal state before cancellation was requested".to_owned(),\n                        ));\n                    }\n                    if !cancellation_acknowledged {\n                        return self.fail_protocol(AdapterSupervisorError::InvalidRuntimeResponse(\n                            "cancellation termination arrived before ACK".to_owned(),\n                        ));\n                    }\n                    let terminal = match response.body {\n                        Some(adapter_frame::Body::InferenceTerminal(terminal)) => terminal,\n                        _ => unreachable!(),\n                    };\n                    let final_sequence = expected_sequence.saturating_sub(1);\n                    self.validate_cancelled_terminal(&terminal, &request, final_sequence)?;\n                    return Ok(CancelledStreamingInferenceResult {\n                        chunks,\n                        text,\n                        terminal,\n                        cancellation_requested: true,\n                        cancellation_acknowledged,\n                    });\n                }\n                Some(adapter_frame::Body::InferenceError(_)) => {\n                    self.validate_inference_outer(&response, &request_frame_id)?;\n                    let failure = match response.body {\n                        Some(adapter_frame::Body::InferenceError(error)) => error,\n                        _ => unreachable!(),\n                    };\n                    return self.inference_failure(failure, &request);\n                }\n                Some(adapter_frame::Body::Error(error)) => {\n                    return self.fail_protocol(AdapterSupervisorError::InvalidRuntimeResponse(\n                        format!("cancellation transport error {}: {}", error.code, error.message),\n                    ))\n                }\n                _ => {\n                    return self.fail_protocol(AdapterSupervisorError::UnexpectedFrame(\n                        "inference cancellation",\n                    ))\n                }\n            }\n        }\n    }\n\n    fn validate_cancelled_terminal(\n        &mut self,\n        terminal: &InferenceTerminal,\n        request: &InferenceRequest,\n        expected_final_sequence: u64,\n    ) -> Result<(), AdapterSupervisorError> {\n        if let Err(error) = validate_contract_version(terminal.contract_version.as_ref()) {\n            return self.fail_protocol(error.into());\n        }\n        let usage = terminal.usage.as_ref();\n        let measurement =\n            usage.and_then(|value| InferenceUsageMeasurement::try_from(value.measurement).ok());\n        let usage_valid = match (measurement, usage) {\n            (Some(InferenceUsageMeasurement::Exact), Some(value)) => {\n                value.input_tokens.is_some()\n                    && value.output_tokens.is_some()\n                    && value.total_tokens.is_some()\n            }\n            (Some(InferenceUsageMeasurement::Unknown), Some(value)) => {\n                value.input_tokens.is_none()\n                    && value.output_tokens.is_none()\n                    && value.total_tokens.is_none()\n            }\n            _ => false,\n        };\n        if terminal.request_id != request.request_id\n            || terminal.attempt_id != request.attempt_id\n            || terminal.final_sequence != expected_final_sequence\n            || InferenceFinishReason::try_from(terminal.finish_reason) != Ok(InferenceFinishReason::Cancelled)\n            || !usage_valid\n        {\n            return self.fail_protocol(AdapterSupervisorError::InvalidRuntimeResponse(\n                "invalid cancellation terminal identity/sequence/finish/usage".to_owned(),\n            ));\n        }\n        Ok(())\n    }\n\n'''
        text = text[:at] + methods + text[at:]
    return text


def patch_rust_tests(text: str) -> str:
    text = replace_once(
        text,
        "        bridge_registry_snapshot, AdapterCommand, AdapterIdentity, AdapterSupervisor,\n        AdapterSupervisorError, SupervisorPolicy,\n",
        "        bridge_registry_snapshot, AdapterCommand, AdapterIdentity, AdapterSupervisor,\n        AdapterSupervisorError, InferenceCancelOutcome, SupervisorPolicy,\n",
        "rust cancellation outcome import",
    )
    anchor = '''#[test]\nfn real_openjarvis_unary_inference_uses_pinned_llamacpp_lane() {\n'''
    if "fn cancellation_before_first_chunk_requires_ack_and_cancelled_terminal()" not in text:
        at = text.find(anchor)
        if at < 0:
            raise RuntimeError("rust unary test anchor missing")
        tests = '''#[test]\nfn cancellation_before_first_chunk_requires_ack_and_cancelled_terminal() {\n    let command = fake_command("stream-cancel-before");\n    let mut supervisor = AdapterSupervisor::start(command, fake_identity(), fast_policy())\n        .expect("connect cancel-before fake sidecar");\n    let result = supervisor\n        .infer_stream_with_cancellation(fake_stream_request(), 0, "cancel before first token")\n        .expect("cancel-before must reach an acknowledged CANCELLED terminal");\n    assert!(result.cancellation_requested);\n    assert!(result.cancellation_acknowledged);\n    assert!(result.chunks.is_empty());\n    assert_eq!(result.terminal.final_sequence, 0);\n    assert_eq!(\n        InferenceFinishReason::try_from(result.terminal.finish_reason),\n        Ok(InferenceFinishReason::Cancelled)\n    );\n}\n\n#[test]\nfn cancellation_during_stream_requires_ack_then_local_terminal() {\n    let command = fake_command("stream-cancel-during");\n    let mut supervisor = AdapterSupervisor::start(command, fake_identity(), fast_policy())\n        .expect("connect cancel-during fake sidecar");\n    let result = supervisor\n        .infer_stream_with_cancellation(fake_stream_request(), 1, "cancel after first token")\n        .expect("cancel-during must reach an acknowledged CANCELLED terminal");\n    assert!(result.cancellation_requested);\n    assert!(result.cancellation_acknowledged);\n    assert_eq!(result.chunks.len(), 1);\n    assert_eq!(result.terminal.final_sequence, 1);\n    assert_eq!(\n        InferenceFinishReason::try_from(result.terminal.finish_reason),\n        Ok(InferenceFinishReason::Cancelled)\n    );\n}\n\n#[test]\nfn cancellation_ack_without_worker_termination_fails_closed() {\n    let command = fake_command("stream-cancel-ignore");\n    let mut policy = fast_policy();\n    policy.request_timeout = Duration::from_millis(120);\n    let mut supervisor = AdapterSupervisor::start(command, fake_identity(), policy)\n        .expect("connect ignore-cancel fake sidecar");\n    let error = supervisor\n        .infer_stream_with_cancellation(fake_stream_request(), 1, "worker ignores cancel")\n        .expect_err("ACK without terminal cessation must never count as cancellation success");\n    assert_eq!(error, AdapterSupervisorError::Timeout("inference cancellation termination"));\n    assert!(supervisor.is_poisoned());\n}\n\n#[test]\nfn cancellation_after_terminal_is_rejected_not_retroactive_success() {\n    let command = fake_command("stream-cancel-after-terminal");\n    let mut supervisor = AdapterSupervisor::start(command, fake_identity(), fast_policy())\n        .expect("connect after-terminal fake sidecar");\n    let request = fake_stream_request();\n    let request_id = request.request_id.clone();\n    let attempt_id = request.attempt_id.clone();\n    let result = supervisor\n        .infer_stream(request)\n        .expect("stream reaches terminal before cancellation");\n    assert_eq!(\n        InferenceFinishReason::try_from(result.terminal.finish_reason),\n        Ok(InferenceFinishReason::Stop)\n    );\n    let outcome = supervisor\n        .cancel_inference(request_id, attempt_id, "too late")\n        .expect("already-terminal cancellation response is a typed non-success outcome");\n    assert_eq!(outcome, InferenceCancelOutcome::AlreadyTerminal);\n    assert!(!supervisor.is_poisoned());\n}\n\n'''
        text = text[:at] + tests + text[at:]
    return text


def apply() -> None:
    targets = {
        "adapters/openjarvis/streaming_inference.py": patch_streaming,
        "adapters/openjarvis/sidecar.py": patch_sidecar,
        "kernel/crates/clever-kernel/tests/fixtures/fake_adapter_sidecar.py": patch_fake_sidecar,
        "kernel/crates/clever-kernel/src/adapter.rs": patch_adapter,
        "kernel/crates/clever-kernel/tests/adapter_supervisor.rs": patch_rust_tests,
    }
    for relative, transform in targets.items():
        path = ROOT / relative
        before = path.read_text(encoding="utf-8")
        after = transform(before)
        path.write_text(after, encoding="utf-8")


def check() -> None:
    required = {
        "adapters/openjarvis/streaming_inference.py": [
            "cancel_requested: Callable[[], bool] | None = None",
            "INFERENCE_FINISH_REASON_CANCELLED",
            "transport ACK was not confirmed",
        ],
        "adapters/openjarvis/sidecar.py": [
            "class _InferenceCoordinator:",
            '"streaming-cancellation"',
            'elif body == "inference_cancel":',
            "CANCEL_ALREADY_TERMINAL",
            "explicit single-flight",
        ],
        "kernel/crates/clever-kernel/src/adapter.rs": [
            "pub enum InferenceCancelOutcome",
            "pub fn infer_stream_with_cancellation(",
            "pub fn cancel_inference(",
            '"streaming-cancellation"',
            "cancellation termination arrived before ACK",
        ],
        "kernel/crates/clever-kernel/tests/fixtures/fake_adapter_sidecar.py": [
            'mode == "stream-cancel-before"',
            'mode == "stream-cancel-during"',
            'mode == "stream-cancel-ignore"',
            'mode == "stream-cancel-after-terminal"',
        ],
        "kernel/crates/clever-kernel/tests/adapter_supervisor.rs": [
            "cancellation_before_first_chunk_requires_ack_and_cancelled_terminal",
            "cancellation_ack_without_worker_termination_fails_closed",
            "cancellation_after_terminal_is_rejected_not_retroactive_success",
        ],
    }
    for relative, needles in required.items():
        text = (ROOT / relative).read_text(encoding="utf-8")
        for needle in needles:
            if needle not in text:
                raise RuntimeError(f"{relative}: missing {needle!r}")


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--apply", action="store_true")
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    if args.apply == args.check:
        parser.error("choose exactly one of --apply or --check")
    if args.apply:
        apply()
    else:
        check()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
